UPDATE email_messages m SET is_read = NOT EXISTS ( SELECT 1 FROM email_message_labels ml JOIN email_labels l ON l.id = ml.label_id WHERE ml.message_id = m.id AND l.provider_label_id = $2 ), is_starred = EXISTS ( SELECT 1 FROM email_message_labels ml JOIN email_labels l ON l.id = ml.label_id WHERE ml.message_id = m.id AND l.provider_label_id = $3 ), updated_at = now() WHERE m.id = ANY($1)
